mapper.sql:
WITH ranked AS (
  SELECT s.*, ROW_NUMBER() OVER(PARTITION BY s.team_id ORDER BY p.submit_beg DESC,p.phase_id DESC) AS rn
  FROM submission s JOIN phase p ON p.phase_id=s.phase_id JOIN track t ON t.track_id=p.track_id
  WHERE t.event_id=#{eventId}
), representative AS (SELECT * FROM ranked WHERE rn=1)

choose.when:
SELECT tm.team_id AS teamId,tm.name,p.phase_id AS phaseId,s.submission_id AS submissionId FROM phase p JOIN track t ON t.track_id=p.track_id JOIN team tm ON tm.track_id=t.track_id LEFT JOIN submission s ON s.team_id=tm.team_id AND s.phase_id=p.phase_id WHERE t.event_id=#{eventId} AND p.phase_id=#{phaseId}
AND s.submission_id IS NOT NULL AND AND s.submission_id IS NULL AND s.submission_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM review_assignment a WHERE a.submission_id=s.submission_id AND a.status IN(0,1))
ORDER BY tm.team_id
